import {
  useId,
  type ChangeEvent,
  type FormEvent,
  type KeyboardEvent,
} from "react";
import "./CommandBox.css";

export type CommandReply = {
  text: string;
  isError: boolean;
};

export type CommandBoxProps = {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  reply?: CommandReply;
  placeholder?: string;
};

export function CommandBox({
  value,
  onChange,
  onSubmit,
  reply,
  placeholder = "Type a command…",
}: CommandBoxProps) {
  const inputId = useId();
  const replyId = useId();

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit(value);
  }

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    onChange(event.target.value);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    // Escape clears the field when there is something to clear.
    if (event.key === "Escape" && value !== "") {
      event.preventDefault();
      onChange("");
    }
  }

  return (
    <div className="command-box">
      <form className="command-box__form" onSubmit={handleSubmit}>
        <label className="sr-only" htmlFor={inputId}>
          Command
        </label>
        <input
          id={inputId}
          className="command-box__input"
          type="text"
          value={value}
          placeholder={placeholder}
          autoComplete="off"
          spellCheck={false}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          aria-describedby={reply ? replyId : undefined}
        />
        <button type="submit" className="command-box__submit">
          Run
        </button>
      </form>

      {reply && (
        <div
          // Remount when the kind changes so screen readers announce the new role.
          key={reply.isError ? "error" : "normal"}
          id={replyId}
          className={
            reply.isError
              ? "command-box__reply command-box__reply--error"
              : "command-box__reply"
          }
          role={reply.isError ? "alert" : "status"}
        >
          {reply.isError && (
            <span className="command-box__tag">Error</span>
          )}
          <span className="command-box__text">{reply.text}</span>
        </div>
      )}
    </div>
  );
}
