  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.command-box {
  display: grid;
  gap: 0.75rem;
  width: min(100%, 40rem);
  font: inherit;
  color: var(--ink);
}

