  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.command-box__input {
  flex: 1 1 auto;
  min-width: 0;
  font: inherit;
  font-size: clamp(1rem, 0.9rem + 0.4vw, 1.25rem);
  color: var(--ink);
  background: var(--slide);
  border: 1px solid var(--muted);
  border-radius: 999px;
  padding: 0.6rem 1.1rem;
}

.command-box__input::placeholder {
  color: var(--muted);
}

.command-box__input:focus {
  border-color: var(--myelin);
}

.command-box__submit {
  font: inherit;
  font-size: clamp(0.9rem, 0.85rem + 0.2vw, 1rem);
  color: var(--slide);
  background: var(--myelin);
  border: 1px solid var(--myelin);
  border-radius: 999px;
  padding: 0.6rem 1.2rem;
  cursor: pointer;
  transition:
    border-color 150ms ease,
    background-color 150ms ease;
}

.command-box__submit:hover {
  border-color: var(--cresyl);
}

.command-box__reply {
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
  padding: 0.6rem 0.9rem;
  border: 1px solid var(--hair);
  border-radius: 0.6rem;
  background: var(--code-bg);
  color: var(--ink);
  font-size: clamp(0.9rem, 0.85rem + 0.2vw, 1rem);
  font-variant-numeric: tabular-nums;
  animation: command-box-in 180ms ease-out;
}

.command-box__reply--error {
  background: var(--cresyl-wash);
  border-color: var(--cresyl);
  border-left-width: 3px;
}

.command-box__tag {
  font-size: 0.75em;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink);
}

.command-box__text {
  min-width: 0;
  overflow-wrap: anywhere;
}

@keyframes command-box-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .command-box__reply {
  animation: none;
}

:root[data-motion="reduce"] .command-box__submit {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .command-box__reply {
    animation: none;
  }

  .command-box__submit {
    transition: none;
  }
}
